WITH base AS (SELECT *, SUBSTRING(location, 1, 4) AS location_prefix, COALESCE(location, 'DIRECT') AS resolved_location FROM departments WHERE budget <= 3719000), metrics AS (SELECT id, dept_name, location, budget, location_prefix, resolved_location, PERCENT_RANK() OVER (PARTITION BY location ORDER BY budget DESC NULLS FIRST) AS budget_percent_rank, ROW_NUMBER() OVER (ORDER BY budget DESC, id) AS row_seq, SUM(budget) OVER w_part AS running_budget FROM base WINDOW w_part AS (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), filtered AS (SELECT *, LOWER(location) AS location_lower, COALESCE(location, 'DIRECT') AS location_clean FROM metrics WHERE running_budget < 17759334), valid AS (SELECT id, dept_name, location, budget, location_prefix, budget_percent_rank, running_budget, location_lower, location_clean, LEAST(running_budget, budget) AS least_running_budget_budget, ROUND(row_seq, 0) AS row_seq_rounded, COALESCE(dept_name, 'DIRECT') AS resolved_dept_name FROM filtered WHERE dept_name IS NOT NULL) SELECT CASE WHEN budget >= 3325000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, CASE WHEN running_budget >= 16741969 THEN 'LARGE' ELSE 'SMALL' END AS running_budget_tier, AVG(running_budget) FILTER (WHERE dept_name = 'Engineering') AS engineering_avg_running_budget, AVG(budget_percent_rank) FILTER (WHERE location = 'Berlin') AS berlin_avg_budget_percent_rank, COUNT(CASE WHEN dept_name = 'Engineering' THEN 1 END) AS engineering_count FROM valid GROUP BY CASE WHEN budget >= 3325000 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN running_budget >= 16741969 THEN 'LARGE' ELSE 'SMALL' END HAVING AVG(budget_percent_rank) FILTER (WHERE location = 'Berlin') < 1000000;
